from docx import Document

# Extract resumes
doc = Document('/app/Candidates_resumes.docx')
with open('/tmp/resumes_raw.txt', 'w') as f:
    for i, p in enumerate(doc.paragraphs):
        if p.text.strip():
            f.write(f'P{i}: {p.text}\n')
    for i, t in enumerate(doc.tables):
        f.write(f'TABLE {i}:\n')
        for r in t.rows:
            cells = [c.text for c in r.cells]
            f.write('  |  '.join(cells) + '\n')
    for i, t in enumerate(doc.tables):
        f.write(f'TABLE_FULL {i}:\n')
        for r in t.rows:
            for cell in r.cells:
